function parse(c){const m=c.match(/rgba?\(([^)]+)\)/); if(!m) return null; const p=m[1].split(/[ ,\/]+/).filter(Boolean).map(Number); return {r:p[0],g:p[1],b:p[2],a:p[3]===undefined?1:p[3]};}
function lum(c){const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(c.r)+0.7152*f(c.g)+0.0722*f(c.b);}
function bg(el){let layers=[];while(el){const c=parse(getComputedStyle(el).backgroundColor);if(c&&c.a>0){layers.push(c); if(c.a>=1)break;} el=el.parentElement;} let r={r:255,g:255,b:255}; for(let i=layers.length-1;i>=0;i--){const l=layers[i]; r={r:l.r*l.a+r.r*(1-l.a),g:l.g*l.a+r.g*(1-l.a),b:l.b*l.a+r.b*(1-l.a)};} return r;}
const out=[];
const walker=document.createTreeWalker(document.getElementById('root'),NodeFilter.SHOW_TEXT);
const seen=new Set();
while(walker.nextNode()){const t=walker.currentNode; if(!t.textContent.trim())continue; const el=t.parentElement; if(seen.has(el))continue; seen.add(el); const cs=getComputedStyle(el); if(cs.visibility==='hidden'||el.offsetParent===null&&cs.position!=='fixed')continue; const fg=parse(cs.color); const b=bg(el); const fgc={r:fg.r*fg.a+b.r*(1-fg.a),g:fg.g*fg.a+b.g*(1-fg.a),b:fg.b*fg.a+b.b*(1-fg.a)}; const L1=lum(fgc),L2=lum(b); const ratio=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05); out.push([el.tagName+'.'+el.className, t.textContent.trim().slice(0,30), cs.color, `rgb(${b.r|0},${b.g|0},${b.b|0})`, ratio.toFixed(2), cs.fontSize, cs.fontWeight].join(' | '));}
